import heapq

def match(orders):
    book = {}  # id -> dict(side, price, qty, time, active)
    buy_heap = []   # entries (-price, time, id)  max-price priority
    sell_heap = []  # entries (price, time, id)   min-price priority
    trades = []

    def add_to_book(o):
        book[o['id']] = o
        if o['side'] == 'buy':
            heapq.heappush(buy_heap, (-o['price'], o['time'], o['id']))
        else:
            heapq.heappush(sell_heap, (o['price'], o['time'], o['id']))

    def valid_top(heap):
        while heap:
            key = heap[0]
            oid = key[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return key
        return None

    def match_incoming(incoming_id, incoming_side, incoming_qty, price_limit):
        if incoming_side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while incoming_qty > 0:
            top = valid_top(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting = book[resting_id]
            resting_price = resting['price']

            if price_limit is not None:
                if incoming_side == 'buy' and resting_price > price_limit:
                    break
                if incoming_side == 'sell' and resting_price < price_limit:
                    break

            # remove top from heap, we will process it
            heapq.heappop(opp_heap)

            trade_qty = min(incoming_qty, resting['qty'])
            if incoming_side == 'buy':
                trades.append([incoming_id, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, incoming_id, resting_price, trade_qty])

            incoming_qty -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] > 0:
                heapq.heappush(opp_heap, top)
            else:
                resting['active'] = False

        return incoming_qty

    for idx, order in enumerate(orders):
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active']:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(oid, side, qty, price)
            if remaining > 0:
                o = {
                    'id': oid,
                    'side': side,
                    'price': price,
                    'qty': remaining,
                    'time': idx,
                    'active': True
                }
                add_to_book(o)

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            match_incoming(oid, side, qty, price)
            # remainder discarded, not added to book

        elif typ == 'market':
            _, oid, side, qty = order
            match_incoming(oid, side, qty, None)
            # remainder discarded, not added to book

    return trades

